// ServerInterface represents all server handlers.
type ServerInterface interface {
	// CommissionNode Commission a device from a code or QR payload, or a discovered device and its passcode.
	// (POST /controller/commission)
	CommissionNode(w http.ResponseWriter, r *http.Request)
	// RemoveCredential Remove a stored credential.
	// (DELETE /controller/credentials)
	RemoveCredential(w http.ResponseWriter, r *http.Request, params RemoveCredentialParams)
	// ListCredentials The stored Wi-Fi and Thread credentials, by name; never a secret.
	// (GET /controller/credentials)
	ListCredentials(w http.ResponseWriter, r *http.Request)
	// SetCredential Store a Wi-Fi credential or a Thread dataset (write-only).
	// (PUT /controller/credentials)
	SetCredential(w http.ResponseWriter, r *http.Request)
	// DiscoverDevices Commissionable devices on the network.
	// (GET /controller/discovery)
	DiscoverDevices(w http.ResponseWriter, r *http.Request, params DiscoverDevicesParams)
	// SetFabricLabel The controller's fabric label, pushed to every node.
	// (PUT /controller/fabric/label)
	SetFabricLabel(w http.ResponseWriter, r *http.Request)
	// ListControllerNodes The commissioned nodes.
	// (GET /controller/nodes)
	ListControllerNodes(w http.ResponseWriter, r *http.Request)
	// DecommissionNode Decommission the node — remove our fabric from it and forget it.
	// (DELETE /controller/nodes/{id})
	DecommissionNode(w http.ResponseWriter, r *http.Request, id NodeID)
	// GetControllerNode One node — record, properties, endpoints with clusters and device types.
	// (GET /controller/nodes/{id})
	GetControllerNode(w http.ResponseWriter, r *http.Request, id NodeID)
	// GetNodeACL The node's access control entries of our fabric.
	// (GET /controller/nodes/{id}/acl)
	GetNodeACL(w http.ResponseWriter, r *http.Request, id NodeID)
	// SetNodeACL Replace our fabric's access control entries on the node.
	// (PUT /controller/nodes/{id}/acl)
	SetNodeACL(w http.ResponseWriter, r *http.Request, id NodeID)
	// ReadNodeAttributes Read concrete attribute paths from the node.
	// (POST /controller/nodes/{id}/attributes)
	ReadNodeAttributes(w http.ResponseWriter, r *http.Request, id NodeID)
	// WriteNodeAttribute Write one attribute.
	// (PUT /controller/nodes/{id}/attributes)
	WriteNodeAttribute(w http.ResponseWriter, r *http.Request, id NodeID)
	// SetNodeAutoSubscribe Turn the node's default subscription on or off.
	// (POST /controller/nodes/{id}/auto-subscribe)
	SetNodeAutoSubscribe(w http.ResponseWriter, r *http.Request, id NodeID)
	// GetNodeBindings The binding targets of every endpoint with a Binding cluster.
	// (GET /controller/nodes/{id}/bindings)
	GetNodeBindings(w http.ResponseWriter, r *http.Request, id NodeID)
	// SetNodeBindings Replace our fabric's binding targets on one endpoint.
	// (PUT /controller/nodes/{id}/bindings)
	SetNodeBindings(w http.ResponseWriter, r *http.Request, id NodeID)
	// InvokeNodeCommand Invoke one command.
	// (POST /controller/nodes/{id}/commands)
	InvokeNodeCommand(w http.ResponseWriter, r *http.Request, id NodeID)
	// DisableNode Disable the node — no connection, no subscription, kept on the fabric.
	// (POST /controller/nodes/{id}/disable)
	DisableNode(w http.ResponseWriter, r *http.Request, id NodeID)
	// EnableNode Enable a disabled node — connect and subscribe again.
	// (POST /controller/nodes/{id}/enable)
	EnableNode(w http.ResponseWriter, r *http.Request, id NodeID)
	// ListNodeFabrics Every fabric on the node, ours marked.
	// (GET /controller/nodes/{id}/fabrics)
	ListNodeFabrics(w http.ResponseWriter, r *http.Request, id NodeID)
	// RemoveNodeFabric Remove another administrator's fabric from the node (RemoveFabric).
	// (DELETE /controller/nodes/{id}/fabrics/{index})
	RemoveNodeFabric(w http.ResponseWriter, r *http.Request, id NodeID, index int)
	// GetNodeIcd The node's intermittently-connected-device state.
	// (GET /controller/nodes/{id}/icd)
	GetNodeIcd(w http.ResponseWriter, r *http.Request, id NodeID)
	// RegisterNodeIcd Register this controller as the node's check-in client.
	// (POST /controller/nodes/{id}/icd/register)
	RegisterNodeIcd(w http.ResponseWriter, r *http.Request, id NodeID)
	// UnregisterNodeIcd Unregister this controller; with force, forget the registration without the node.
	// (POST /controller/nodes/{id}/icd/unregister)
	UnregisterNodeIcd(w http.ResponseWriter, r *http.Request, id NodeID)
	// InterviewNode Read the whole node again, without data version filters.
	// (POST /controller/nodes/{id}/interview)
	InterviewNode(w http.ResponseWriter, r *http.Request, id NodeID)
	// OpenNodeWindow Open an enhanced commissioning window on the node for another administrator.
	// (POST /controller/nodes/{id}/window)
	OpenNodeWindow(w http.ResponseWriter, r *http.Request, id NodeID)
	// CloseNodeWindow Revoke the node's commissioning window.
	// (POST /controller/nodes/{id}/window/close)
	CloseNodeWindow(w http.ResponseWriter, r *http.Request, id NodeID)
	// GetControllerStatus The controller's fabric, its node count and capabilities.
	// (GET /controller/status)
	GetControllerStatus(w http.ResponseWriter, r *http.Request)
	// ControllerStream Server-sent events of the controller.
	// (GET /controller/stream)
	ControllerStream(w http.ResponseWriter, r *http.Request)
	// ListUpdates The software update queue.
	// (GET /controller/updates)
	ListUpdates(w http.ResponseWriter, r *http.Request)
	// CheckUpdates Ask every node for an available update.
	// (POST /controller/updates/check)
	CheckUpdates(w http.ResponseWriter, r *http.Request)
	// ConsentUpdate Consent to one node's update to a version.
	// (POST /controller/updates/consent)
	ConsentUpdate(w http.ResponseWriter, r *http.Request)
}

